protected void cleanup()
{
    InventCleanupWHSInventSumService                     inventCleanupWHSInventSumService;
    InventCleanupWHSInventSumWithInventDimContract       dataContract;
    Query                                       query;
    InventSum                                   inventSumMain;
    int64                                       recCount;
    boolean                                     shouldContinue = true;

    while select crosscompany inventSumMain
        group by DataAreaId
    {
        changeCompany(inventSumMain.dataAreaId)
        {
            recCount = this.countRecords(tableNum(InventSum));

            inventCleanupWHSInventSumService = new InventCleanupWHSInventSumService();
            dataContract = new InventCleanupWHSInventSumWithInventDimContract();
            query = new Query(querystr(InventCleanupWHSInventSum));
            dataContract.parmQuery(SysOperationHelper::base64Encode(query.pack()));
            dataContract.parmDeleteWhenNotUpdatedForDays(cleanupTaskSettings.cleanupDaysForCompany());
            dataContract.parmMaximumExecutionTimeInHours(cleanupTaskSettings.MaxRunTimeHours);
            inventCleanupWHSInventSumService.cleanupInventSumWithInventDim(dataContract);

            shouldContinue = this.addDeletedRecords(recCount - this.countRecords(tableNum(InventSum)));
        }

        if (!shouldContinue)
        {
            break;
        }
    }
}

public DEV_CleanUpTaskName getTaskName()
{
    ;
    return "Warehouse management on-hand entries cleanup(Standard)";
}

public void estimate()
{
    InventSum                       inventSumMain;

    info("Company, Closed, RecCount");

    while select crosscompany count(RecId) from inventSumMain
        group by DataAreaId, Closed
    {
        info(strFmt("%1, %2, %3", inventSumMain.dataAreaId, inventSumMain.Closed, inventSumMain.RecId));
    }
}
